contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: value to set as MinSum. No ether transfers are needed.
    function run(uint _val) public payable {
        // Observe initial MinSum and contract balance
        uint beforeMin = c.MinSum(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // Try to call SetMinSum and capture whether it reverted
        bool reverted;
        c.SetMinSum(_val); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after-state
        uint afterMin = c.MinSum(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General rule:
        // - If the call succeeded (did not revert) then MinSum equals _val and contract balance unchanged.
        // - If it reverted then MinSum unchanged and contract balance unchanged.
        assert((!reverted && afterMin == _val && afterBal == beforeBal)
               || (reverted && afterMin == beforeMin && afterBal == beforeBal));
    }

    receive() external payable {}
}

