pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 _val) internal {
        uint256 beforeMin;
        try c.MinSum() returns (uint256 __r) { beforeMin = __r; } catch { return; }
        uint beforeBal = address(c).balance;
        bool reverted;
        try c.SetMinSum(_val) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterMin;
        try c.MinSum() returns (uint256 __r) { afterMin = __r; } catch { return; }
        uint afterBal = address(c).balance;
        assertTrue((!reverted && afterMin == _val && afterBal == beforeBal)
               || (reverted && afterMin == beforeMin && afterBal == beforeBal));
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
